import { AlertTriangle, Info } from "lucide-react"
import { cn } from "@/lib/utils"

/**
 * The one place the Health Tips disclaimer wording lives.
 *
 * Health Tips are AI-generated, so every surface that shows them carries this text. It is
 * a component rather than copy pasted into the page so the wording cannot drift between
 * the banner at the top and the note under the results, and so legal/clinical can change
 * it in a single edit.
 */

export const AI_DISCLAIMER_TITLE = "AI-generated health information"

export const AI_DISCLAIMER_BODY =
  "These tips are generated by AI and may be incomplete, out of date or wrong. They are " +
  "general information, not medical advice, a diagnosis or a treatment plan, and they " +
  "should not replace a conversation with a qualified health professional."

export const AI_DISCLAIMER_EMERGENCY =
  "If you think you may have a medical emergency, contact your local emergency number or " +
  "go to the nearest health facility right away. Do not wait for an online answer."

type AiDisclaimerProps = {
  /**
   * `banner` is the full notice, shown above the search and always visible.
   * `inline` is the short reminder repeated under results, so it is still on screen
   * when someone has scrolled past the banner.
   */
  variant?: "banner" | "inline"
  className?: string
}

export function AiDisclaimer({ variant = "banner", className }: AiDisclaimerProps) {
  if (variant === "inline") {
    return (
      <p
        role="note"
        className={cn(
          "flex gap-2 rounded-xl bg-[#fff6ec] px-3 py-2.5 text-xs leading-5 text-[#8a5a2b] ring-1 ring-[#f0c9a4]",
          className,
        )}
      >
        <Info className="mt-0.5 size-3.5 shrink-0" aria-hidden="true" />
        <span>
          AI-generated and not fully reliable. Check with a health professional before acting
          on anything here.
        </span>
      </p>
    )
  }

  return (
    <section
      role="note"
      aria-label={AI_DISCLAIMER_TITLE}
      className={cn(
        "flex gap-3 rounded-2xl border border-[#f0c9a4] bg-[#fff6ec] p-4 text-sm text-[#8a5a2b]",
        className,
      )}
    >
      <AlertTriangle className="mt-0.5 size-4 shrink-0" aria-hidden="true" />
      <div className="space-y-1.5">
        <h2 className="font-semibold">{AI_DISCLAIMER_TITLE}</h2>
        <p>{AI_DISCLAIMER_BODY}</p>
        <p className="font-medium">{AI_DISCLAIMER_EMERGENCY}</p>
      </div>
    </section>
  )
}
